		{Dataset: "source", Distance: 1, Path: []string{"source", "report"}},
		{Dataset: "z", Distance: 1, Path: []string{"z", "report"}},
		{Dataset: "a", Distance: 2, Path: []string{"a", "z", "report"}},
		{Dataset: "b", Distance: 2, Path: []string{"b", "c", "report"}},
