1	package chainledger
2	
3	import (
4		"reflect"
5		"slices"
6		"sort"
7		"strconv"
8		"strings"
9		"testing"
10	)
11	
12	// Names carrying raw, invalid UTF-8 bytes. Registration and Rename accept them
13	// verbatim; only ExportUpstreamLineage of a closure that contains them rejects.
14	const (
15		repairBadName      = "mid\xff" // intermediate dataset blocking report's export
16		repairStrangerName = "stranger\xfe"
17	)
18	
19	// repairLineageScenario builds the lineage for the rename-repair regression.
20	// src participates in merge's derivation twice: directly, and through the
21	// intermediate dataset whose registered name contains an invalid UTF-8 byte.
22	// report derives from merge; side derives from the bad intermediate but takes
23	// no part in report's derivation; a standalone dataset with a different
24	// invalid name is registered outside report's closure. Registration of every
25	// invalid name must succeed.
26	func repairLineageScenario(t *testing.T) map[string]*Lineage {
27		t.Helper()
28		return buildRegisteredGraph(t, [][]string{
29			{"src"},
30			{repairBadName, "src"},
31			{"merge", "src", repairBadName}, // branch merge: src direct and through the bad node
32			{"report", "merge"},
33			{"side", repairBadName}, // downstream of the bad node outside report's closure
34			{repairStrangerName},    // invalid name, unrelated to report's derivation
35		})
36	}
37	
38	// assertExportBlockedByInvalidName exports target and requires the documented
39	// failure shape: an empty string, no partial JSON, and the offending name in
40	// Go-quoted form so the original illegal bytes stay distinguishable.
41	func assertExportBlockedByInvalidName(t *testing.T, graph map[string]*Lineage, target, bad string) {
42		t.Helper()
43		out, err := ExportUpstreamLineage(graph, target)
44		if err == nil {
45			t.Fatalf("ExportUpstreamLineage(%q) with invalid name %q in its lineage succeeded: %s",
46				target, bad, out)
47		}
48		if out != "" {
49			t.Errorf("ExportUpstreamLineage(%q) returned partial content %q, want empty string", target, out)
50		}
51		if !strings.Contains(err.Error(), "not valid UTF-8") {
52			t.Errorf("ExportUpstreamLineage(%q) error %q must be the encoding error", target, err)
53		}
54		quoted := strconv.Quote(bad)
55		if !strings.Contains(err.Error(), quoted) {
56			t.Errorf("ExportUpstreamLineage(%q) error %q must show the original bytes %s in Go-quoted form",
57				target, err, quoted)
58		}
59	}
60	
61	// assertEdgesFollowRegisteredParents reads the exported edges as a consumer
62	// would and confirms every edge runs from a registered direct upstream to the
63	// dataset derived from it — the documented from -> to direction.
64	func assertEdgesFollowRegisteredParents(t *testing.T, graph map[string]*Lineage, doc exportDocument) {
65		t.Helper()
66		for _, e := range doc.Edges {
67			if !slices.Contains(graph[e.To].Parents, e.From) {
68				t.Errorf("exported edge %q -> %q is not a registered direct dependency; parents of %q are %v",
69					e.From, e.To, e.To, graph[e.To].Parents)
70			}
71		}
72	}
73	
74	// End-to-end repair flow: an invalid name anywhere in the target's closure
75	// blocks the full upstream export until the dataset is renamed to a legal,
76	// unused name; afterwards the same derived data exports with every original
77	// dependency intact, including both routes of the branch merge.
78	func TestExportUpstreamLineageRenameRepairsInvalidName(t *testing.T) {
79		graph := repairLineageScenario(t)
80		assertConsistent(t, graph)
81		assertEntry(t, graph, "src", nil, []string{repairBadName, "merge"})
82		assertEntry(t, graph, repairBadName, []string{"src"}, []string{"merge", "side"})
83		assertEntry(t, graph, "merge", []string{"src", repairBadName}, []string{"report"})
84	
85		// Before the repair, the invalid name blocks the export whether it sits in
86		// the closure indirectly (report) or as a direct upstream (merge). The
87		// failure returns no document and leaves the registry and every neighbor
88		// list exactly as it was.
89		before := snapshotExportGraph(graph)
90		assertExportBlockedByInvalidName(t, graph, "report", repairBadName)
91		assertExportBlockedByInvalidName(t, graph, "merge", repairBadName)
92		assertGraphUnchanged(t, before, graph)
93	
94		// The encoding rule belongs to the export only: registry queries still
95		// answer with the raw registered name.
96		ups := mustUpstreams(t, graph, "report")
97		if got, want := upstreamNames(ups), []string{"merge", repairBadName, "src"}; !reflect.DeepEqual(got, want) {
98			t.Fatalf("upstreams before repair = %q, want %q (raw invalid name still listed)", got, want)
99		}
100		assertGraphUnchanged(t, before, graph)
101	
102		// Repair the name. Rename accepts the raw old name and the node keeps its
103		// exact slot in every neighbor's list; no edge is added, dropped or merged.
104		mustRename(t, graph, repairBadName, "repaired")
105		assertConsistent(t, graph)
106		if _, ok := graph[repairBadName]; ok {
107			t.Fatal("old invalid name still registered after rename")
108		}
109		if got, want := len(graph), 6; got != want {
110			t.Fatalf("dataset count = %d, want %d (rename must not merge or add nodes)", got, want)
111		}
112		assertEntry(t, graph, "repaired", []string{"src"}, []string{"merge", "side"})
113		assertEntry(t, graph, "src", nil, []string{"repaired", "merge"}) // first slot rewritten in place
114		assertEntry(t, graph, "merge", []string{"src", "repaired"}, []string{"report"})
115		assertEntry(t, graph, "side", []string{"repaired"}, nil)
116	
117		// The export of the same derived data now succeeds, even though an
118		// unrelated invalid name remains registered elsewhere in the graph.
119		exportBefore := snapshotExportGraph(graph)
120		out := mustExport(t, graph, "report")
121		doc := parseExport(t, out)
122	
123		wantNodes := []string{"merge", "repaired", "report", "src"}
124		wantEdges := [][2]string{
125			{"merge", "report"},
126			{"repaired", "merge"},
127			{"src", "merge"},
128			{"src", "repaired"},
129		}
130		if len(doc.Nodes) != 4 || len(doc.Edges) != 4 {
131			t.Errorf("node/edge counts = %d nodes, %d edges, want 4 and 4 (the original relationships)",
132				len(doc.Nodes), len(doc.Edges))
133		}
134		if !reflect.DeepEqual(doc.Nodes, wantNodes) {
135			t.Errorf("nodes = %q, want %q", doc.Nodes, wantNodes)
136		}
137		if !slices.IsSorted(doc.Nodes) {
138			t.Errorf("nodes are not in Go string order: %q", doc.Nodes)
139		}
140		if got := exportEdgeNames(doc); !reflect.DeepEqual(got, wantEdges) {
141			t.Errorf("edges = %q, want %q", got, wantEdges)
142		}
143		if !sort.SliceIsSorted(doc.Edges, func(i, j int) bool {
144			if doc.Edges[i].From != doc.Edges[j].From {
145				return doc.Edges[i].From < doc.Edges[j].From
146			}
147			return doc.Edges[i].To < doc.Edges[j].To
148		}) {
149			t.Errorf("edges are not ordered by from then to: %v", exportEdgeNames(doc))
150		}
151		assertEdgesFollowRegisteredParents(t, graph, doc)
152	
153		// The branch merge survives in full: src reaches merge directly, and the
154		// longer src -> repaired -> merge route stays even though the shorter one
155		// exists. The repaired dataset must not be lost as "already reachable".
156		edgeSet := map[[2]string]bool{}
157		for _, e := range wantEdges {
158			edgeSet[e] = true
159		}
160		for _, want := range [][2]string{
161			{"src", "merge"},      // short, direct route
162			{"src", "repaired"},   // longer branch, edge into the repaired node
163			{"repaired", "merge"}, // longer branch, edge out of it
164		} {
165			if !edgeSet[want] {
166				t.Errorf("relationship %v missing from the repaired export %v", want, wantEdges)
167			}
168		}
169	
170		// The old name leaves the document entirely: no raw illegal byte and no
171		// node decoded back to it. Unrelated nodes never enter report's closure.
172		if strings.Contains(out, "\xff") {
173			t.Errorf("illegal byte from the old name leaked into the export: %s", out)
174		}
175		for _, name := range doc.Nodes {
176			if name == repairBadName {
177				t.Errorf("old invalid name decoded back from the export: %q", name)
178			}
179		}
180		for _, excluded := range []string{"side", "stranger"} {
181			if strings.Contains(out, excluded) {
182				t.Errorf("node outside report's derivation (%q) leaked into the export: %s", excluded, out)
183			}
184		}
185	
186		// The repaired export must be byte-identical to that of an always-valid
187		// twin lineage holding the same relationships: the repair changed names
188		// only, never the node or dependency set.
189		twin := buildRegisteredGraph(t, [][]string{
190			{"src"},
191			{"repaired", "src"},
192			{"merge", "src", "repaired"},
193			{"report", "merge"},
194			{"side", "repaired"},
